(async () => {
  const url='https://site.api.espn.com/apis/site/v2/sports/basketball/nba/scoreboard?dates=20251001-20260630&teams=13&limit=1000';
  const r=await fetch(url);
  const j=await r.json();
  const events=(j.events||[]).map(e=>({id:e.id,date:e.date,name:e.name,shortName:e.shortName,status:e.status?.type?.description,completed:e.status?.type?.completed,competitions:e.competitions?.map(c=>({competitors:c.competitors?.map(t=>({homeAway:t.homeAway,team:t.team?.displayName,abbrev:t.team?.abbreviation,score:t.score,winner:t.winner,record:t.records?.map(r=>r.summary).join(', ')}))}))}));
  return JSON.stringify({count:events.length, events:events.slice(-10)}, null, 2);
})()
